raw:
{
  "spells": [
    {
      "id": "spell_wind_01",
      "theory": "招风术将一点魔力注入两米内的空气，使近处气团沿施术者指定的方向流动。气流松软，只够推开浮烟、吹散薄雾或摇动轻质布料。它不会自行寻找烟源，也不会增强为持续风暴，三十秒后魔力耗尽，空气恢复原有状态。",
      "casting": "五指并拢，掌心朝目标轻推，同时于心中默数三拍。推掌时手腕须保持平直，若中途翻掌或数错节拍，气流方向便会偏斜。",
      "failure": "掌心推空时只激起一小股乱流，扬起的尘土反而扑向施术者面部。若默数过快，气流可能在指缝间散尽，连一根羽毛也吹不动，只留下短暂的凉意。",
      "counters": [
        "用厚布或木板挡在气流路径上，风势便被截断。",
        "站到上风处或以身体护住火源，可令气流无法触及目标。"
      ],
      "socialConsequences": "河谷乡民在灶台倒烟时常用它救急，邻里视为寻常家务手段。城中公会记录显示，若在货栈内乱推掌风，可能吹散待称的香料粉末，招来商贩索赔。港务方面则留意有人借风势改动船帆索具，若因此妨碍装卸，会被追究责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时气流方向常偏，只够吹动一缕轻烟。",
        "稍熟后能稳定推散两米内的浮尘，不再迷眼。",
        "熟练者可在三拍内收势，避免吹动邻近的轻物。",
        "极熟者能控制气流只拂过指定角落，仍限三十秒。"
      ]
    },
    {
      "id": "spell_wind_02",
      "theory": "拂尘术把魔力化成一层贴附于物体表面的气流，沿表面滑过时带走松散尘土与草屑。它只能作用于两米内可见的干燥表面，对油污、霉斑或嵌入木纹的泥垢无效。气流持续三十秒后自然消散，尘土落回原处，物体本身不受损伤。",
      "casting": "食中二指并拢，自物体一侧向另一侧横抹，指腹距表面约一拳。抹动三次，每次间隔一次呼吸，收指时掌心朝下。",
      "failure": "指距过近时，气流会集中成一股，把尘土推向物体边缘而非吹离。若间隔太短，尘土只是从一处挪到另一处，表面仍留一层薄灰，光线斜照时格外明显。",
      "counters": [
        "给物体罩上细布，尘土便随布被提起，不再受气流影响。",
        "在物体表面涂一层薄油，使尘土粘附，气流无法剥离。"
      ],
      "socialConsequences": "抄写员和书商欢迎这种小术，能快速清理纸面浮灰而不伤墨迹。陶匠却担心强风吹裂未干的坯体，因此作坊内只允许在坯体离手后使用。城中和港口的货主若见人对着待售货物施术，会要求先确认不会吹走标签或混入邻堆的粉尘。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把尘土推到边缘，留下一条灰线。",
        "稍熟后能一次拂净书本封面，不触及内页。",
        "熟练者可控制气流贴面滑过，不吹动旁边的纸片。",
        "极熟者能在三十秒内分次清理多个小物件，力道均匀。"
      ]
    },
    {
      "id": "spell_wind_03",
      "theory": "传声线把说话声压入一条两米内指定方向的短气流，使声音沿气流传递，途中的人也能听见。气流只能携带人声，不能传递乐音或巨响，距离超过三米便散失。三十秒后气流消失，最后几个字会变得模糊。",
      "casting": "以拇指与食指捏住下唇，向目标方向轻轻吐气，同时低声说出要传的话。捏唇须保持稳定，若手指松开或吐气过猛，声音便会四散。",
      "failure": "吐气太急时，气流会在中途断裂，话声变成一串含混的元音。若捏唇不紧，声音从两侧漏出，近处的人只听到零碎音节，远处的人则完全听不见。",
      "counters": [
        "在气流路径上放置一盆水或厚布帘，声线便被吸收。",
        "大声说话或敲击金属，可盖过传声线携带的语音。"
      ],
      "socialConsequences": "河谷的乡约见证常借它向对岸喊话，省去绕路过桥的工夫。城中公会提醒，在集市用传声线叫卖可能干扰邻摊议价，屡次如此会被要求调整位置或时段。港口则关注是否有人借传声线向离岸船只递送未经登记的指令，若涉及货单改动，港务会追究责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时话声断续，对方只能听到零散词语。",
        "稍熟后能传清一句短话，超过三米仍会散失。",
        "熟练者可控制音量，只让目标位置听清内容。",
        "极熟者能在三十秒内分次传话，字句依然清晰。"
      ]
    }
  ]
}
